from recursion import reverse_rec

def test_reverse_single():
    assert reverse_rec("z") == "z"

def test_reverse_empty():
    assert reverse_rec("") == ""

def test_reverse_long():
    assert reverse_rec("abcdef") == "fedcba"


from stats import clamp

def test_clamp_upper():
    assert clamp(14, 0, 10) == 10

def test_clamp_lower():
    assert clamp(-3, 0, 10) == 0

def test_clamp_bad_range():
    import pytest
    with pytest.raises(ValueError):
        clamp(5, 10, 0)
